1  uint32_t mg_crc32(uint32_t crc, const char *buf, size_t len) {
     2    static const uint32_t crclut[16] = {
     3        // table for polynomial 0xEDB88320 (reflected)
     4        0x00000000, 0x1DB71064, 0x3B6E20C8, 0x26D930AC, 0x76DC4190, 0x6B6B51F4,
     5        0x4DB26158, 0x5005713C, 0xEDB88320, 0xF00F9344, 0xD6D6A3E8, 0xCB61B38C,
     6        0x9B64C2B0, 0x86D3D2D4, 0xA00AE278, 0xBDBDF21C};
     7    crc = ~crc;
     8    while (len--) {
     9      uint8_t b = *(uint8_t *) buf++;
    10      crc = crclut[(crc ^ b) & 0x0F] ^ (crc >> 4);
    11      crc = crclut[(crc ^ (b >> 4)) & 0x0F] ^ (crc >> 4);
    12    }
    13    return ~crc;
    14  }
